import { useEffect, useMemo, useState } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import { useSelector } from 'react-redux'
import AdminSidebar from '../../components/AdminSidebar'
import AdminHeader from '../../components/AdminHeader'
import {
	useGetSchoolByIdQuery,
	useGetSubjectsBySchoolQuery,
} from '../../slices/admin/schoolAdminApiSlice'
import {
	normalizeGradeLevels,
	subjectIncludesGradeLevel,
} from '../../utils/gradeLevel'
import {
	normalizeUniversityPrograms,
	subjectIncludesProgram,
} from '../../utils/universityProgram'
import { isUniversitySchool } from '../../utils/schoolType'
import {
	TeacherSubjectsGrid,
	SubjectCardActionsStudentsSchoolAdmin,
} from '../teachers/TeacherSubjectsGrid'
import '../../App.css'

const GradCapIcon = () => (
	<svg
		width='22'
		height='22'
		viewBox='0 0 24 24'
		fill='none'
		xmlns='http://www.w3.org/2000/svg'
	>
		<path
			d='M3 9L12 4L21 9L12 14L3 9Z'
			fill='#1e293b'
			stroke='#1e293b'
			strokeWidth='1.2'
			strokeLinejoin='round'
		/>
		<path
			d='M7 11.5V15C7 16.657 9.239 18 12 18C14.761 18 17 16.657 17 15V11.5'
			stroke='#1e293b'
			strokeWidth='1.2'
			strokeLinecap='round'
			strokeLinejoin='round'
		/>
	</svg>
)

function resolveSchoolId (school) {
	if (!school) {
		return null
	}
	if (typeof school === 'string') {
		return school
	}
	if (typeof school === 'object' && school._id) {
		return String(school._id)
	}
	return null
}

function SchooldAdminStudentsScreen () {
	const navigate = useNavigate()
	const { schoolAdminInfo } = useSelector((state) => state.authSchoolAdmin)
	const schoolId = schoolAdminInfo
		? resolveSchoolId(schoolAdminInfo.school)
		: null

	const {
		data: subjects = [],
		isLoading,
		isError,
		refetch,
	} = useGetSubjectsBySchoolQuery(schoolId, {
		skip: !schoolId,
	})

	const {
		data: schoolData,
		isLoading: isLoadingSchool,
	} = useGetSchoolByIdQuery(schoolId, {
		skip: !schoolId,
	})

	const [isSidebarOpen, setIsSidebarOpen] = useState(
		window.innerWidth > 768,
	)
	const [selectedCohortId, setSelectedCohortId] = useState('')

	const gradesLevels = normalizeGradeLevels(schoolData?.gradesLevels)
	const programs = normalizeUniversityPrograms(schoolData?.programs)
	const isUniversity = isUniversitySchool(schoolData?.schoolType)
	const cohorts = isUniversity ? programs : gradesLevels
	const hasCohorts = cohorts.length > 0
	const isPageLoading = isLoading || isLoadingSchool
	const subjectsList = useMemo(
		() => (Array.isArray(subjects) ? subjects : []),
		[subjects],
	)
	const filteredSubjects = useMemo(() => {
		if (selectedCohortId === '') {
			return subjectsList
		}
		const selectedCohort = cohorts.find(
			(item) => String(item._id) === selectedCohortId,
		)
		if (!selectedCohort) {
			return subjectsList
		}
		return subjectsList.filter(
			(subject) => isUniversity
				? subjectIncludesProgram(subject.program, selectedCohort)
				: subjectIncludesGradeLevel(
					subject.gradesLevel,
					selectedCohort,
				),
		)
	}, [subjectsList, selectedCohortId, cohorts, isUniversity])
	const subjectCountByCohort = useMemo(() => {
		const counts = new Map()
		for (const cohort of cohorts) {
			const id = String(cohort._id)
			const count = subjectsList.filter(
				(subject) => isUniversity
					? subjectIncludesProgram(subject.program, cohort)
					: subjectIncludesGradeLevel(
						subject.gradesLevel,
						cohort,
					),
			).length
			counts.set(id, count)
		}
		return counts
	}, [subjectsList, cohorts, isUniversity])

	const handleSelectCohortFilter = (cohortId) => {
		setSelectedCohortId(cohortId)
	}

	const toggleSidebar = () => {
		setIsSidebarOpen(!isSidebarOpen)
	}

	useEffect(() => {
		if (!schoolAdminInfo) {
			navigate('/schooladmins/login', { replace: true })
		}
	}, [schoolAdminInfo, navigate])

	if (!schoolAdminInfo) {
		return null
	}

	if (!schoolId) {
		return (
			<div className='chat-app chat-app--teacher-login ask-screen'>
				<div className='main-container'>
					<AdminSidebar
						isOpen={isSidebarOpen}
						toggleSidebar={toggleSidebar}
					/>
					<div className='main-content'>
						<AdminHeader
							isSidebarOpen={isSidebarOpen}
							toggleSidebar={toggleSidebar}
						/>
						<div className='content-area content-area--login'>
							<div className='center-content2 login-screen login-screen--wide'>
								<div className='login-card'>
									<div className='login-card__accent' aria-hidden />
									<div className='login-card__header'>
										<h1 className='login-card__title'>
											<br />
											Aún no hay escuela
										</h1>
										<p className='login-card__subtitle login-card__subtitle--wide'>
											Registra tu escuela primero; después
											podrás ver estudiantes por materia.
										</p>
									</div>
									<p className='login-card__subtitle login-card__subtitle--wide'>
										<Link to='/schooladmins/registerschool'>
											Registra tu escuela
										</Link>
									</p>
								</div>
							</div>
						</div>
					</div>
				</div>
			</div>
		)
	}

	return (
		<div className='chat-app chat-app--teacher-login ask-screen'>
			<div className='main-container'>
				<AdminSidebar
					isOpen={isSidebarOpen}
					toggleSidebar={toggleSidebar}
				/>
				<div className='main-content'>
					<AdminHeader
						isSidebarOpen={isSidebarOpen}
						toggleSidebar={toggleSidebar}
					/>
					<div className='content-area'>
						<TeacherSubjectsGrid
							pageTitle='Estudiantes por materia'
							pageSubtitle={
								isUniversity
									? (
										'Elige una materia para ver los estudiantes '
										+ 'inscritos y su actividad. Filtra por '
										+ 'programa para acotar la lista.'
									)
									: (
										'Elige una materia para ver los estudiantes '
										+ 'inscritos y su actividad.'
									)
							}
							afterSubtitle={
								!isPageLoading && !isError ? (
									<>
										<div className='teacher-subjects-page__cta'>
											<Link
												to='/schooladmins/addstudents'
												className='teacher-subjects-page__add-btn'
											>
												<span
													className='teacher-subjects-page__add-btn-icon'
													aria-hidden
												>
													+
												</span>
												<span>Agregar estudiantes</span>
											</Link>
										</div>
										{subjectsList.length > 0 && hasCohorts ? (
											<div
												className='teacher-subjects-page__grade-filter'
												role='group'
												aria-label={isUniversity
													? 'Filtrar materias por programa'
													: 'Filtrar materias por grado'}
											>
												<div className='teacher-subjects-page__grade-filter-header'>
													<span
														className='teacher-subjects-page__grade-filter-icon'
														aria-hidden
													>
														<GradCapIcon />
													</span>
													<span className='teacher-subjects-page__grade-filter-label'>
														{isUniversity
															? 'Filtrar por programa'
															: 'Filtrar por grado'}
													</span>
													{selectedCohortId !== '' && (
														<span className='teacher-subjects-page__grade-filter-count'>
															{filteredSubjects.length}{' '}
															{filteredSubjects.length === 1
																? 'materia'
																: 'materias'}
														</span>
													)}
												</div>
												<div className='teacher-subjects-page__grade-filter-pills'>
													<button
														type='button'
														className={
															'teacher-subjects-page__grade-pill' +
															(selectedCohortId === ''
																? ' teacher-subjects-page__grade-pill--active'
																: '')
														}
														onClick={() =>
															handleSelectCohortFilter('')}
														aria-pressed={selectedCohortId === ''}
													>
														{isUniversity
															? 'Todos los programas'
															: 'Todos los grados'}
														<span className='teacher-subjects-page__grade-pill-count'>
															{subjectsList.length}
														</span>
													</button>
													{cohorts.map((cohort) => {
														const cohortId = String(cohort._id)
														const isActive =
															selectedCohortId === cohortId
														const count =
															subjectCountByCohort.get(
																cohortId,
															) ?? 0

														return (
															<button
																key={cohortId}
																type='button'
																className={
																	'teacher-subjects-page__grade-pill' +
																	(isActive
																		? ' teacher-subjects-page__grade-pill--active'
																		: '')
																}
																onClick={() =>
																	handleSelectCohortFilter(
																		cohortId,
																	)}
																aria-pressed={isActive}
															>
																{isUniversity
																	? cohort.name
																	: ` ${cohort.name}`}
																{isUniversity
																	&& cohort.department
																	? ` (${cohort.department})`
																	: ''}
																<span className='teacher-subjects-page__grade-pill-count'>
																	{count}
																</span>
															</button>
														)
													})}
												</div>
											</div>
										) : null}
									</>
								) : null
							}
							emptyMessage={
								selectedCohortId !== '' && subjectsList.length > 0
									? (isUniversity
										? 'Aún no hay materias para este programa.'
										: 'Aún no hay materias para este grado.')
									: 'Aún no hay materias. Crea materias primero; '
										+ 'los estudiantes inscritos aparecerán aquí.'
							}
							subjects={filteredSubjects}
							isLoading={isPageLoading}
							isError={isError}
							refetch={refetch}
							isUniversity={isUniversity}
							renderCardActions={(subject) => (
								<SubjectCardActionsStudentsSchoolAdmin
									subjectId={String(subject._id)}
								/>
							)}
						/>
					</div>
				</div>
			</div>
		</div>
	)
}

export default SchooldAdminStudentsScreen
